    private static DrawingImage Mark(double width, double height, params (string Fill, string Data)[] layers)
    {
        var group = new DrawingGroup();
        // A clear box the size of the view box keeps the mark's padding (DrawingImage sizes to its drawing's bounds).
        group.Children.Add(new GeometryDrawing { Brush = Brushes.Transparent, Geometry = new RectangleGeometry(new Rect(0, 0, width, height)) });
        foreach (var (fill, data) in layers)
        {
            group.Children.Add(new GeometryDrawing { Brush = new ImmutableSolidColorBrush(Color.Parse(fill)), Geometry = ArcIcons.Parse(data) });
        }
        return new DrawingImage { Drawing = group };
    }
